#!/usr/bin/env bash
# wake-codex.sh — hand a fresh handoff to a headless Codex run.
# Generated by `install.sh --target codex`.
#
# Codex has no timer either, so the supervisor (outside the host) starts this.
# `codex exec` runs one non-interactive turn with the given prompt; pass a
# session id as the second argument to resume that thread instead of starting a
# new one (`codex exec resume <sid> <prompt>`). The Codex desktop app's own
# automation (intervalMinutes / quotaAware / model / reasoningEffort) is an
# alternative wake path — see docs/scheduling.md.
#
# Working directory (R1): a worker must run in the *card's project target
# directory*, and only this host-local glue can know it — the supervisor knows a
# project identity and nothing about directories (the board holds none).
#   TP_PROJECT       the card's board project identity (the supervisor sets it)
#   TP_PROJECTS_JSON the local map; defaults to the one beside the installed skill
#   TP_NODE          node to resolve with; defaults to `node` on PATH (the
#                    supervisor passes its own interpreter, since cron/launchd
#                    run with a minimal PATH)
# The directory is resolved from that map and validated (absolute, exists, is a
# directory). If it cannot be resolved this script **exits 3 without starting a
# worker** — running a session in the wrong checkout is worse than not waking one.
#
# Headless permission boundary (docs/scheduling.md §Headless permission
# boundary): this script must NOT default to bypassing permissions — no
# approvals-and-sandbox bypass flag. Run under the non-interactive sandbox /
# approval policy; a bypass needs explicit written authorization, documented here.
#
#   wake-codex.sh "<handoff>"            # a fresh non-interactive turn
#   wake-codex.sh "<handoff>" <sid>      # resume thread <sid>
set -eu

prompt="${1:-}"
sid="${2:-}"

if [ -z "$prompt" ]; then
  echo "wake-codex: a handoff prompt is required" >&2
  exit 2
fi

projects_json="${TP_PROJECTS_JSON:-$(dirname "$0")/../skills/meerkat-taskpanel/projects.json}"
if ! cwd="$("${TP_NODE:-node}" "{{REPO}}/scripts/wake-cwd.mjs" --project "${TP_PROJECT:-}" --projects-json "$projects_json")"; then
  echo "wake-codex: refusing to wake a worker without a target directory" >&2
  exit 3
fi
cd "$cwd"
echo "wake-codex: working directory $cwd" >&2

if [ -n "$sid" ]; then
  exec codex exec resume "$sid" "$prompt"
fi

exec codex exec "$prompt"
